"""Generate documentation and table manifests from executed research artifacts."""
from pathlib import Path
import csv
import json
from src import config
from src.research.protocol import PROTOCOL,VERSION


def generate(manifest,experiment,legacy,monitor,readiness,figures):
    folder=config.PROJECT_ROOT/'docs/research';folder.mkdir(parents=True,exist_ok=True)
    outline=['Abstract','Introduction','Related Work','Study Area and Data','Operational Forecast Protocol','AQI Methodology','AirGuard Residual-Correction Framework','Predictive Uncertainty','Vulnerability-Aware Advisory Framework','Experimental Design','Baselines','Results','Spatial Generalisation','Severe-Event Performance','Ablation','Uncertainty Calibration','Advisory Safety Trade-offs','Prospective Deployment Evaluation','Limitations','Ethics / Health Communication','Reproducibility','Conclusion']
    documents={
        'RESEARCH_PROTOCOL':f"Protocol `{VERSION}` is versioned in `src/research/protocol.json`. Issuance: 20:00 IST, next midnight-to-midnight IST day. Prefetch at 19:50, freeze inputs available by 20:00, issue within 10 minutes or skip. The actual issue timestamp is retained. Retrieval/availability, model reference time, measured hour end and target availability are checked separately. No after-cutoff input is a predictor. Upstream CAMS initialization is unknown for this live API; actual first retrieval is the availability anchor. Rationale: {PROTOCOL['rationale']}",
        'RESEARCH_QUESTIONS':"H1: India-specific residual correction may improve on raw CAMS and persistence. H2: calibrated advisory distributions may reduce under-warning with acceptable over-warning. Both are hypotheses. RQ1 forecast skill; RQ2 unseen city/station generalisation; RQ3 high pollution and Severe; RQ4 conditional interval coverage; RQ5 advisory trade-offs. No novelty or superiority is established.",
        'DATA_DICTIONARY':"provider_snapshots preserve actual provider payload, retrieval and availability; feature_snapshots preserve cutoff, target and A–F groups; station_daily_targets preserve one station's measured-hour evidence, coverage and quality; dataset_versions and experiment_registry preserve hashes, protocol, seed, Git SHA plus dirty-tree hash and dependency versions. research_forecast_runs preserve raw CAMS, nullable correction, nullable intervals, station binding and immutable actual issuance. Verification is a separate immutable join. Legacy forecast_runs preserve variable-time on-demand CAMS snapshots and are excluded from fixed-time experiments.",
        'FEATURE_AVAILABILITY':"A CAMS: future valid times permitted only from forecasts retrieved before cutoff. B observations: hourly bin end and first retrieval <= cutoff; no target-day observations. Lags 1/3/6/12/24/48h and 24h mean/median/std/delta/slope count distinct hours. C weather: archived or prospectively captured forecast, never observed tomorrow weather. D calendar is known in advance. E coordinates and model grid are contextual. F fire detections require acquisition and retrieval <= cutoff and are excluded until ablation. Predictor imputation fits on training only; targets are never imputed. Missing boundary-layer data stays missing. Precise festival, elevation and upwind features are not implemented without defensible sources.",
        'BASELINES':"B0 train-only station/month climatology with month/global-median fallbacks; B1 latest complete measured rolling CPCB-style AQI available at issuance; B2 raw CAMS from the frozen forecast; B3 legacy LightGBM only in its separate historical experiment; B4 ridge residual; B5 LightGBM residual; B6 XGBoost residual; direct LightGBM AQI is also compared. The primary correction family is predeclared LightGBM. All primary comparisons share exactly the same station/date rows. No modern baseline score exists yet.",
        'VALIDATION_PROTOCOL':"Split globally by target date, keeping all stations on a date together. Predeclare 90 training dates, 30 calibration dates, 30 test dates and a one-day embargo at each boundary. Prior outcomes must be available before the following partition's first issuance. Report expanding and bounded rolling windows separately. Latest 30 dates are locked final test; choose A0–A4 on earlier expanding folds only. Fixed estimator hyperparameters avoid final-test tuning. Leave-city and leave-station out are time-ordered. Report n for every subgroup. This complete design needs at least 182 distinct eligible target dates for one validation fold plus the separate final test. Seven-day paired moving-block bootstrap preserves all station pairs on each resampled date; no DM p-value is invented.",
        'UNCERTAINTY':"Offline CQR fits 80% and 90% residual quantile models on training, calibrates on later dates, then evaluates the untouched final test. Sort crossing raw quantiles; nonnegative widening uses daily maximum calibration errors so station duplicates do not inflate calibration n. Report marginal width/coverage and observed category/city/season coverage, including Severe n. Serial dependence invalidates automatic exchangeability guarantees; coverage is empirical. Severe targets above the last closed breakpoint are censored and cannot receive exact coverage scores. Wide intervals alone never trigger abstention. Split/Mondrian/online conformal comparisons remain pending; they are not claimed implemented or validated.",
        'ADVISORY_POLICY':"Version experimental-category-warning-v1. Under-warning means issued AQI category below observed category; over-warning means above; distance is absolute category difference. Seven exposure cohorts use predeclared experimental targets 5% or 10%, not clinical risk thresholds. Train quantiles 0.50/0.65/0.75/0.85/0.95 on training. Select only on calibration using date-max under-warning and a Bonferroni binomial upper-bound screen; minimize over-warning among qualifying candidates. Report no selected policy if insufficient. Dates are dependent, so this screen is not a proven time-series guarantee. The final test stays untouched until selection. Production retains deterministic CPCB/WHO-style guidance; experimental policies are not enabled.",
        'PROSPECTIVE_VALIDATION':"Existing on-demand immutable forecast recording started 10 Oct 2026; it is not a fixed-20:00 experiment. Fixed-time research issuance was configured after that day's cutoff; first eligible local issuance is 11 Oct at 20:00 IST, targeting 12 Oct. No backdating. Local Windows tasks need an awake logged-in PC. Three Supabase cron jobs (prefetch, issuance, verification) are registered but inactive pending explicit production approval and endpoint checks. Before target, bind one measured station within 25 km only from metadata retrieved before cutoff. No adequate station means nationwide CAMS mode with no station-bound verification. Later retrieval can verify outcomes but cannot enter predictors. Incomplete targets are rejected. No 30/90-day claim before enough valid distinct days and actual window coverage exist.",
        'LIMITATIONS':"Zero eligible operational training pairs currently. The archive experiment is PENDING — ADS credential/terms required and was explicitly skipped by the user. No reanalysis/current past-days substitute. Sparse modern measured data lacks three eligible pollutants at each audited station-day. CAMS grid is 0.4 degrees (~45 km), provider-interpolated from native three-hour values. Severe open concentration bands yield >=401 lower bounds; exact Severe MAE is not identifiable under this method. Legacy city daily data and modern station hourly records are mismatched for drift attribution. FIRMS remains optional context. Hindi/Tamil guidance remains disabled. No automatic retraining. Browser visual/mobile review remains outstanding; automated component and HTTP tests are not certification. Supabase pg_net's platform-owned PUBLIC privileges and extension placement warning remain; AirGuard tables and secret functions are private.",
        'PRIOR_ART':"Initial targeted review is in prior_art.json. CAMS already offers station-optimised machine-learning MOS using observations and forecast weather. Riccio and Chianese (2024) already combine CAMS correction, meteorology, spatial post-processing and probabilistic calibration. CQR and conformal risk control are established methods. India's Delhi EWS already combines chemistry forecasts, observations and fires. The defensible candidate contribution is an evaluated India-specific operational protocol and cohort advisory trade-off, not API aggregation. Full-text extraction and an exhaustive novelty search remain incomplete; literature_review_complete is false. See linked primary sources below.",
        'PAPER_OUTLINE':'\n\n'.join(f'## {i+1}. {name}\n\n'+('PENDING: populate only from executed held-out and prospective results. No results exist for the locked station-correction experiment.' if name in ['Results','Spatial Generalisation','Severe-Event Performance','Ablation','Uncertainty Calibration','Advisory Safety Trade-offs','Prospective Deployment Evaluation'] else 'Draft scope: follow the locked protocol and conservative claim register; citations and evidence required.') for i,name in enumerate(outline))
    }
    priors=json.loads((folder/'prior_art.json').read_text(encoding='utf8'))
    documents['PRIOR_ART']+='\n\n'+'\n\n'.join(f"- [{x['title']}]({x['url']}) ({x['year']}): {x['overlap']}" for x in priors['entries'])
    for name,text in documents.items():(folder/(name+'.md')).write_text('# '+name.replace('_',' ')+'\n\n'+text+'\n',encoding='utf8')
    table_dir=config.RESULTS_DIR/'research/tables';table_dir.mkdir(parents=True,exist_ok=True)
    statuses=[]
    for name in ('dataset_description','station_city_coverage','baseline_comparison','rolling_origin','leave_city_out','category_metrics','seasonal_metrics','ablation','uncertainty_coverage','advisory_tradeoff','prospective_results','latency_cost'):
        with (table_dir/(name+'.csv')).open('w',encoding='utf8',newline='') as f:
            writer=csv.DictWriter(f,fieldnames=['table','status','n','reason']);writer.writeheader()
            writer.writerow({'table':name,'status':'PENDING' if name!='dataset_description' else 'AUDITED','n':manifest['pairs'],'reason':'Eligible fixed-time measured pairs unavailable' if not manifest['pairs'] else 'See executed experiment JSON; expanded table export pending'})
        statuses.append(name)
    if experiment.get('final_test'):
        pd_rows=[{'model':k,**v} for k,v in experiment['final_test'].items()]
        import pandas as pd
        pd.DataFrame(pd_rows).to_csv(table_dir/'baseline_comparison.csv',index=False)
        pd.DataFrame(experiment['spatial']).to_csv(table_dir/'leave_city_out.csv',index=False)
    lines=['# Research upgrade acceptance report','',f"Status: {readiness['status']}. {readiness['passed']}/{readiness['total']} readiness checks have evidence. This is not a forecast accuracy score.",'']
    sections={
        'A — Architecture audited':'Existing Next.js/Vercel Python/Supabase application retained. Source inventory and baseline are results/research/repository_audit.json. Nationwide live sources, SQL cache, budgets, leases and legacy models preserved.',
        'B — Scientific inconsistencies':"Live forecast explicitly labels CAMS nationwide mode and unvalidated station correction. Historical research moved to /research/legacy. Prior past-fields backtest is exploratory, not archived day-ahead validation. The original city-ordered row CV trains through 2019 against 2015-era validation rows in all four folds; its temporal-validation claim is invalid. Future splitters require explicit date metadata and whole-date embargoed splits; original weights and scores remain preserved and labelled. Fold-specific preprocessing/selection still needs nested evaluation. R², SHAP, counterfactual policy and HAI retain their limited meanings.",
        'C — Protocol':f"{VERSION}: 20:00 IST daily; next IST calendar day; <=20:00 availability cutoff; measured station-only target; minimum three pollutants including PM, 16 hourly bins, complete eight-hour gas windows. No late backdating.",
        'D — Dataset':f"Operational pairs {manifest['pairs']}, eligible stations {manifest['stations']}, cities {manifest['cities']}, dates {manifest['dates']}. Historical station-day rows {legacy['rows']}, stations {legacy['stations']}, cities {legacy['cities']}, dates {legacy['dates']}; these reported daily AQIs are a separate dataset. Source coverage, missingness and rejected target days are generated JSON files.",
        'E — Baselines':'Climatology, measured persistence and raw CAMS implemented, with ridge, LightGBM, XGBoost and direct-AQI comparison. Legacy B3 is not applicable to the new operational rows until separately validated.',
        'F — Models':'Offline residual correction: measured target minus raw CAMS; add predicted residual back. Physical nonnegative floor recorded. No new research model trained or activated on real operational pairs yet.',
        'G — Primary results':json.dumps(experiment.get('final_test') or {'n':manifest['pairs'],'MAE':None,'RMSE':None,'bias':None,'category_metrics':None}),
        'H — CAMS improvement':json.dumps(experiment.get('comparison') or {'absolute':None,'percentage':None,'CI':None,'p_value':None,'reason':'No eligible evaluation pairs'}),
        'I — Rolling-origin':'Date-blocked rolling and expanding implementation tested. Operational fold results pending.',
        'J — Spatial':'Leave-city and leave-station framework implemented. Operational results pending; deployment support denies unvalidated stations.',
        'K — Severe events':'Numeric Severe error cannot be fabricated from censored >=401 targets. Exact target regression excludes lower bounds; category-only ledger verification retains them. Severe-support evidence is absent.',
        'L — Ablation':'A0–A4 implemented for CAMS/weather/station/spatial groups. A5 FIRMS pending captured fire features and evidence; excluded from predictor. No winning feature set claimed.',
        'M — Uncertainty':'CQR 80%/90% framework implemented and tested. Empirical/conditional coverage and widths pending real pairs. No operational calibrated interval.',
        'N — Advisory':'Versioned seven-cohort experimental calibration screen, under/over-warning and severity-distance metrics implemented. No cohort risk control or clinical validation claimed.',
        'O — Prospective':'Immutable variable-time CAMS records exist. Fixed-time local tasks installed; first actual issuance pending. Fixed-time outcomes zero. No retrospective record counts as prospective. Cloud cron remains inactive.',
        'P — Migrations':'20261010174656_research_forecast_protocol.sql (15 private tables and inactive schedules); 20261010180429_research_ledger_guards.sql (stronger period/station/outcome/error guards). Canonical application migration history retained.',
        'Q — API/UI':'/api/research/status, /research, /research/track-record, /research/legacy added. Existing /live and nationwide APIs preserved. Consumer values remain CAMS while correction is unsupported.',
        'R — Tests':'See results/research/verification.json for final executed checks. Synthetic fixtures exercise software only and never produce paper metrics.',
        'S — Build':'See final verification artifact; production replacement requires explicit approval. Preview deployment belongs to the existing webapp project.',
        'T — Readiness':f"{readiness['passed']}/{readiness['total']} evidence checks; NOT RESEARCH READY. Detailed booleans and evidence hashes in research_readiness.json.",
        'U — Limitations':documents['LIMITATIONS'],
        'V — Supported claims':'The project provides labelled nationwide raw CAMS estimates, secure Supabase storage, immutable pre-target baseline records and a tested issue-time research framework.',
        'W — Unsupported claims':'AirGuard ML beats CAMS; correction generalises nationwide; calibrated Severe uncertainty; controlled cohort under-warning; prospective 30/90-day skill; clinical benefit; novelty.',
        'X — Manual actions':'Archive access was skipped per user instruction and remains optional pending ADS credentials/terms. Production deployment and cloud schedule activation require explicit approval. Calendar time and adequate measured station data are needed for experiments; no credential substitutes can manufacture them.'}
    for name,text in sections.items():lines.extend(['## '+name,'',text,''])
    (folder/'ACCEPTANCE_REPORT.md').write_text('\n'.join(lines),encoding='utf8')
    return {'documents':list(documents),'tables':statuses}
